import { apiUrl } from "../config/api"
import { SUPABASE_PUBLISHABLE_KEY } from "../config/supabase-public"
import { supabase } from "./supabase"

/**
 * Connecting a domain they already own — FCS-081.
 * ============================================================================
 * Same contract as the buy pipeline: each step returns
 * `{ success, step, data, log, error }` and its `data` is merged into one
 * running state. Same panel renders it, so the two jobs look like one
 * product.
 *
 * ── IT IS REAL, AND THAT CHANGES THE DESIGN ────────────────────────────────
 * Unlike buying — which has no registrar endpoint yet — every step here hits
 * the deployed `domain-connect` function, which hits Cloudflare. So there is
 * no rehearsal transport and no made-up data anywhere in this file: if
 * Cloudflare says no, the step fails and says what Cloudflare said.
 *
 * ── THE WAITING ROOM IS THE HARD PART ──────────────────────────────────────
 * Between "here are your nameservers" and "it works" sits a visit to the
 * customer's registrar, which may be tomorrow. The pipeline is built to be
 * LEFT and COME BACK TO: `resume` reads the stored row on page load and puts
 * the panel back where it was, so somebody who changed their nameservers
 * overnight returns to a Check button rather than to step one.
 */

export const PHASES = ["Your domain", "Hand over", "Confirm"]

export const STEPS = [
  {
    id: "domain",
    phase: "Your domain",
    label: "Which domain is it?",
    detail: "The address you already own, such as yourbusiness.com.",
    mutates: false,
  },
  {
    id: "preflight",
    phase: "Your domain",
    label: "Check we can set it up",
    detail: "Confirms our DNS account is reachable before anything is created.",
    mutates: false,
  },
  {
    id: "zone",
    phase: "Hand over",
    label: "Create the DNS zone",
    detail: "Adds your domain to Cloudflare, which issues the two nameservers below.",
    mutates: true,
  },
  {
    id: "handover",
    phase: "Hand over",
    label: "Change it at your registrar",
    detail: "The one thing only you can do: paste these two where you bought the domain.",
    mutates: false,
  },
  {
    id: "confirm",
    phase: "Confirm",
    label: "Confirm it has taken effect",
    detail: "Asks Cloudflare whether your registrar's change has gone through yet.",
    mutates: false,
  },
  {
    id: "point",
    phase: "Confirm",
    label: "Point it at your website",
    detail: "Writes the records that send your domain to the site you published.",
    mutates: true,
  },
]

export function emptyState() {
  return {
    domain: "",
    nameservers: [],
    status: "",
    registrar: "godaddy",
    confirmedAt: null,
    target: "",
    // Records already at the domain that the customer has not yet agreed to replace (FCS-120).
    existing: [],
    replace: false,
  }
}

const ok = (step, data, log) => ({ success: true, step, data: data || {}, log: log || [] })
const bad = (step, error, log) => ({ success: false, step, data: {}, log: log || [], error })

/** POSTs to the deployed function as the signed-in user. */
async function call(body) {
  const client = supabase()
  const { data } = client ? await client.auth.getSession() : { data: null }
  const token = data?.session?.access_token
  if (!token) return { ok: false, status: 401, body: { message: "Log in to connect a domain." } }

  let res
  try {
    res = await fetch(apiUrl("domain-connect"), {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        apikey: SUPABASE_PUBLISHABLE_KEY,
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify(body),
    })
  } catch {
    return { ok: false, status: 0, body: { message: "Could not reach the server." } }
  }

  const payload = await res.json().catch(() => ({}))
  return { ok: res.ok, status: res.status, body: payload }
}

/**
 * What the server already knows, for a page load.
 *
 * Returns null when there is nothing stored, so a first visit starts at step
 * one rather than showing an empty "connected domain" card.
 */
export async function resume() {
  const res = await call({ action: "status" })
  return res.ok && res.body.domain ? { ...res.body.domain, wired: Boolean(res.body.wired) } : null
}

export const transport = {
  /* Step 1 is the customer typing. It validates nothing itself — the server
     owns what counts as a domain, because the server is what has to create a
     zone for it, and two different opinions about that is a bug waiting. */
  async domain(state) {
    if (!state.domain) return bad("domain", "Type the domain you own.")
    return ok("domain", {}, [state.domain])
  },

  async preflight() {
    const res = await call({ action: "preflight" })
    if (!res.ok) return bad("preflight", res.body.message || "Could not reach Cloudflare.")
    if (!res.body.canCreateZones) {
      /* A precise failure, not a generic one. This exact case is live right
         now — the configured token can edit DNS but not create zones — and
         "something went wrong" would have somebody retrying for an hour. */
      return bad(
        "preflight",
        res.body.message ||
          "Our DNS account cannot create zones yet. We have been told; nothing you can fix."
      )
    }
    return ok("preflight", {}, [`Ready${res.body.account?.name ? ` — ${res.body.account.name}` : ""}.`])
  },

  async zone(state) {
    const res = await call({ action: "start", domain: state.domain })
    if (!res.ok) return bad("zone", res.body.message || "The zone could not be created.")
    const row = res.body.domain || {}
    return ok(
      "zone",
      {
        domain: row.domain || state.domain,
        nameservers: row.nameservers || [],
        status: row.status || "pending",
        confirmedAt: row.confirmedAt || null,
      },
      [`${row.domain} added. ${(row.nameservers || []).length} nameservers issued.`]
    )
  },

  /* Nothing to run: the work is at the registrar. It is a step rather than a
     paragraph because it belongs in the numbered list — leaving it out would
     make the pipeline look like it does something it does not. */
  async handover(state) {
    if (!state.nameservers.length) return bad("handover", "No nameservers were issued yet.")
    return ok("handover", {}, ["Waiting on your registrar."])
  },

  async confirm() {
    const res = await call({ action: "check" })
    if (!res.ok) return bad("confirm", res.body.message || "Cloudflare did not answer.")
    const row = res.body.domain || {}
    if (row.status !== "active") {
      /* Not an error — the commonest, most expected outcome. Nameserver
         changes take anywhere from minutes to a day, and a red cross here
         would read as "it failed" when the honest answer is "not yet". */
      return bad(
        "confirm",
        "Not yet — your registrar has not published the change. This can take up to 24 hours. Press Check again later.",
        [`Cloudflare says: ${res.body.cloudflareStatus || row.status}`]
      )
    }
    return ok("confirm", { status: "active", confirmedAt: row.confirmedAt }, [
      `${row.domain} is confirmed.`,
    ])
  },

  /* Puts the website on the domain (FCS-120): four A records to GitHub Pages, a www record, the domain set on the Pages site,
     HTTPS. If the domain already sends visitors somewhere else, that is SAID and nothing is changed until the customer
     agrees (`replace`). Their mail and other records are never touched. Safe to ask again: it can still be building. */
  async point(state) {
    let res = null
    for (let attempt = 0; attempt < 6; attempt += 1) {
      res = await call({ action: "wire", replace: state.replace === true })
      if (!res.ok) return bad("point", res.body.message || "Your website could not be put on the domain.")
      if (res.body.status === "needs-confirm") {
        return {
          success: false,
          step: "point",
          data: { existing: res.body.existing || [] },
          log: [],
          error: "Your domain already sends visitors somewhere else. Nothing was changed.",
        }
      }
      if (res.body.status === "live") break
      await new Promise(resolve => setTimeout(resolve, 8000))
    }
    if (res?.body?.status !== "live") {
      return bad("point", "Your website is still being put on the domain. Press Try again in a minute: nothing is lost.")
    }
    return ok("point", { target: res.body.url || "", existing: [], replace: false }, [`Live at ${res.body.url}.`])
  },
}

export async function runStep(step, state) {
  const fn = transport[step.id]
  if (typeof fn !== "function") return bad(step.id, `No "${step.id}" step.`)
  try {
    return await fn(state)
  } catch (err) {
    return bad(step.id, err?.message || "That step failed.")
  }
}
