import * as React from "react"
import PageSpinner from "../PageSpinner"
import { Link, navigate } from "gatsby"
import { useAuth } from "../../context/auth"
import { apiUrl } from "../../config/api"
import { SUPABASE_PUBLISHABLE_KEY } from "../../config/supabase-public"
import { cleanQuery, searchDomains } from "../../lib/domains"
import { MIN_PRICE_CENTS, coverageFor, money, retailOf } from "../../lib/domain-pipeline"
import { configured, supabase } from "../../lib/supabase"
import ConnectDomain from "../account/ConnectDomain"
import DomainPipeline from "../account/DomainPipeline"
import { MOVING, buy } from "../../lib/domain-buy"
import { adoptViewAsFromUrl, getViewAs, onTestModeChange, rememberViewAsEmail } from "../../lib/test-mode"
import * as s from "./DomainStudio.module.css"

/**
 * Getting a domain — FCS-094.
 * ============================================================================
 * Its own page, with no account sidebar: the account screen is where you
 * manage things, and this is one errand with one way through it.
 *
 *   free account          their free address, then search. Prices are shown,
 *                         and every domain under the cutoff says it is FREE
 *                         UPON SIGN UP. They cannot buy, so the way forward
 *                         from any result is "sign up", not a dead button.
 *   paid, no domain       a fork: "already have one — set that up" or "don't
 *                         have one — find one". Then the same search, where
 *                         the free ones are simply free.
 *   has a domain          what they have, and where it stands.
 *
 * ── EVERY PRICE IS THE SERVER'S ────────────────────────────────────────────
 * The floor ($16.99) and whether something is free are decided in
 * domain-search, not here, so what this screen shows and what a purchase
 * would charge cannot drift apart. This only draws what came back.
 *
 * ── "FREE" CLAIMS FOLLOW THE ADMIN'S SWITCH ────────────────────────────────
 * Search returns the offer as it stands. Switched off, no result is labelled
 * free and the upsell stops promising a credit; nothing here keeps its own
 * copy of the answer.
 */

const FREE_HOST = "freecontractorservices.com"

const Glass = () => (
  <svg viewBox="0 0 20 20" width="18" height="18" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" aria-hidden="true">
    <circle cx="9" cy="9" r="5.5" />
    <path d="m13.5 13.5 4 4" />
  </svg>
)

const Cross = () => (
  <svg viewBox="0 0 20 20" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" aria-hidden="true">
    <path d="m5 5 10 10M15 5 5 15" />
  </svg>
)

/** What the account says about itself. */
function useAccount() {
  const { user, ready } = useAuth()
  const [data, setData] = React.useState(null)
  const [error, setError] = React.useState("")
  // Bumped when an administrator's sandbox changes while viewing (FCS-095).
  const [tick, setTick] = React.useState(0)

  React.useEffect(() => {
    if (ready && configured() && !user) navigate("/log-in?next=/account/domain", { replace: true })
  }, [ready, user])

  React.useEffect(() => onTestModeChange(() => getViewAs() && setTick(t => t + 1)), [])

  React.useEffect(() => {
    if (!ready || !user) return undefined
    let alive = true
    adoptViewAsFromUrl()
    ;(async () => {
      const client = supabase()
      const { data: session } = await client.auth.getSession()
      const token = session?.session?.access_token
      const res = await fetch(apiUrl("my-account"), {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          apikey: SUPABASE_PUBLISHABLE_KEY,
          Authorization: `Bearer ${token || SUPABASE_PUBLISHABLE_KEY}`,
        },
        body: "{}",
      }).catch(() => null)
      const body = res ? await res.json().catch(() => ({})) : {}
      if (!alive) return
      if (!res || !res.ok) return setError(body.message || "We could not load your account just now.")
      if (body.viewing) rememberViewAsEmail(body.viewing.email)
      setData(body)
    })()
    return () => {
      alive = false
    }
  }, [ready, user, tick])

  return { ready: ready && Boolean(user), data, error }
}

const Result = ({ domain, paid, offerOn, onSelect, chosen }) => {
  const retail = retailOf(domain)
  const taken = !domain.registrable
  const free = offerOn && domain.free
  // What THEY would pay for the first year, credit and all.
  const due = retail ? coverageFor(retail.registrationCents, { creditOn: offerOn }).dueCents : 0

  return (
    <li className={s.row} data-taken={taken ? "true" : undefined} data-chosen={chosen ? "true" : undefined}>
      <div className={s.rowMain}>
        <span className={s.rowName}>{domain.name}</span>
        <span className={s.chips}>
          {taken ? (
            <span className={s.chip} data-tone="taken">Taken</span>
          ) : (
            <span className={s.chip} data-tone="ok">Available</span>
          )}
          {!taken && free ? (
            <span className={s.chip} data-tone="free">
              {paid ? "FREE" : "FREE UPON SIGN UP"}
            </span>
          ) : null}
        </span>
      </div>

      {!taken && retail ? (
        <div className={s.rowPrice}>
          {paid ? (
            /* What THEY would pay: the retail price crossed out where
               something comes off it, then what is left. Every row says what
               it will actually cost. */
            <>
              {due < retail.registrationCents ? (
                <span className={s.price} data-struck="true">{money(retail.registrationCents)}</span>
              ) : null}
              <span className={s.priceFree} data-paid={due > 0 ? "true" : undefined}>{money(due)}</span>
              <span className={s.priceNote}>
                first year{due < retail.registrationCents ? ", after your credit" : ""}, then{" "}
                {money(retail.renewalCents)}
              </span>
            </>
          ) : (
            <>
              <span className={s.price} data-struck={free ? "true" : undefined}>
                {money(retail.registrationCents)}
              </span>
              <span className={s.priceNote}>
                {free ? "free with a plan · " : ""}
                first year, then {money(retail.renewalCents)}
              </span>
            </>
          )}
        </div>
      ) : null}

      {!taken && retail ? (
        paid ? (
          <button type="button" className={s.select} onClick={() => onSelect(domain)} data-on={chosen ? "true" : undefined}>
            {chosen ? "Selected" : "Select"}
          </button>
        ) : (
          <Link to="/website-builder" className={s.signup}>
            Sign up to get this
          </Link>
        )
      ) : null}
    </li>
  )
}

const DomainStudio = () => {
  const { ready, data, error } = useAccount()
  const [mode, setMode] = React.useState(null) // paid, no domain: "find" | "own"
  const [query, setQuery] = React.useState("")
  const [state, setState] = React.useState({ status: "idle", domains: [], offer: null, reason: "", asked: "" })
  const [chosen, setChosen] = React.useState(null)
  const abort = React.useRef(null)

  const plan = data?.plan || { id: "free" }
  const paid = plan.id !== "free"

  /* An order that is already under way (FCS-120): back from Stripe (?order=…), or a tab that was closed part-way. The
     server is carrying it out; this only shows where it has got to. */
  const [resume, setResume] = React.useState(null) // { orderId } | { cancelled: true } | null
  React.useEffect(() => {
    if (!paid || typeof window === "undefined") return
    const q = new URLSearchParams(window.location.search)
    const id = q.get("order")
    if (id && q.get("checkout") === "cancelled") return setResume({ cancelled: true })
    if (id) return setResume({ orderId: id })
    buy({ action: "status" }).then(res => {
      const o = res.ok ? res.body.order : null
      if (o && [...MOVING, "needs-attention"].includes(o.status)) setResume({ orderId: o.id })
    })
  }, [paid])
  const own = data?.ownDomain // null: none · object: has one · undefined: unknown
  const offerOn = (state.offer ? state.offer.enabled : data?.offer?.enabled) !== false
  const slug = data?.site?.subdomain || ""

  const search = async event => {
    event?.preventDefault()
    const q = cleanQuery(query)
    if (!q) return
    abort.current?.abort()
    const controller = new AbortController()
    abort.current = controller

    setChosen(null)
    setState({ status: "searching", domains: [], offer: null, reason: "", asked: q })
    const result = await searchDomains(q, { signal: controller.signal })
    if (controller.signal.aborted) return
    setState({
      status: result.ok ? "done" : "failed",
      domains: result.domains,
      offer: result.offer,
      reason: result.reason,
      asked: q,
    })
  }

  const clear = () => {
    setQuery("")
    setChosen(null)
    setState({ status: "idle", domains: [], offer: null, reason: "", asked: "" })
  }

  if (!ready || (!data && !error)) {
    return <PageSpinner label="Getting your domain page ready…" />
  }
  if (error) {
    return <p className={s.error}>{error}</p>
  }

  const best = state.domains.slice(0, 6)
  const more = state.domains.slice(6)
  const showFind = !paid || mode === "find" || (own === null && mode === "find")
  const showOwn = paid && mode === "own"
  const fork = paid && own === null && mode === null
  const hasOne = paid && own && typeof own === "object"

  return (
    <div className={s.page}>
      <Link to="/account/#settings" className={s.back}>
        ‹ Back to settings
      </Link>

      {resume?.cancelled ? (
        <p className={s.note} data-testid="domain-cancelled">
          You did not complete the payment, so nothing was bought and you have not been charged.
        </p>
      ) : null}
      {resume?.orderId ? (
        <section className={s.panel} aria-label="Finishing your domain" data-testid="domain-resume">
          <h2 className={s.h2}>Finishing your domain</h2>
          <DomainPipeline compact={!data?.isAdmin} resume={resume} />
        </section>
      ) : null}

      {/* ── free: where they live now, and the way out of it ── */}
      {!paid ? (
        <section className={s.free} aria-label="Your free address">
          <div className={s.freeAddress}>
            <span className={s.freeLabel}>Your free address</span>
            <span className={s.bar}>
              <span className={s.lock} aria-hidden="true">●</span>
              <span className={s.barText}>
                <span className={s.barSlug} data-empty={slug ? undefined : "true"}>
                  {slug || "yourname"}
                </span>
                .{FREE_HOST}
              </span>
            </span>
          </div>
          {offerOn ? (
            <div className={s.upsell}>
              <span className={s.upsellText}>
                <strong>Sign up now and get a free domain credit for the first year.</strong>
                <span>
                  Pick a domain of your own below. Anything marked FREE is covered, and the rest
                  comes off by {money(MIN_PRICE_CENTS)}.
                </span>
              </span>
              <Link to="/website-builder" className={s.upsellButton}>
                Sign up now
              </Link>
            </div>
          ) : null}
        </section>
      ) : null}

      {/* ── paid, nothing yet: the fork ── */}
      {fork ? (
        <section className={s.fork} aria-label="Set up a domain">
          <button type="button" className={s.forkCard} onClick={() => setMode("own")}>
            <span className={s.forkTitle}>Already have a domain?</span>
            <span className={s.forkText}>Let&apos;s set that up for you now.</span>
            <span className={s.forkGo}>Set it up →</span>
          </button>
          <button type="button" className={s.forkCard} data-alt="true" onClick={() => setMode("find")}>
            <span className={s.forkTitle}>Don&apos;t have a domain yet…</span>
            <span className={s.forkText}>Let&apos;s find you one now.</span>
            <span className={s.forkGo}>Find a domain →</span>
          </button>
        </section>
      ) : null}

      {/* ── already has one ── */}
      {hasOne ? (
        <section className={s.panel}>
          <h2 className={s.h2}>Your domain</h2>
          <p className={s.note}>
            <strong>{own.domain}</strong> — {own.status === "active" ? "connected" : own.status}.
          </p>
          {own.source === "connected" ? <ConnectDomain /> : null}
        </section>
      ) : null}

      {showOwn ? (
        <section className={s.panel}>
          <button type="button" className={s.linkBtn} onClick={() => setMode(null)}>
            ‹ Choose something else
          </button>
          <ConnectDomain />
        </section>
      ) : null}

      {/* ── search ── */}
      {showFind && !hasOne ? (
        <>
          {paid ? (
            <button type="button" className={s.linkBtn} onClick={() => setMode(null)}>
              ‹ Choose something else
            </button>
          ) : null}

          <section className={s.hero}>
            <div className={s.heroBg} aria-hidden="true">
              <span>.com</span>
              <span>.co</span>
              <span>.site</span>
              <span>.net</span>
              <span>.org</span>
            </div>
            <h1 className={s.h1}>
              Find Your Perfect <span className={s.h1Accent}>Domain</span> Name Today
            </h1>
            <p className={s.lede}>
              Secure the right address for your business and put it on your website without
              touching a setting.
            </p>

            <form className={s.search} onSubmit={search} role="search">
              <span className={s.field}>
                <input
                  className={s.input}
                  value={query}
                  onChange={e => setQuery(e.target.value)}
                  placeholder="yourbusiness"
                  autoComplete="off"
                  spellCheck="false"
                  aria-label="Name to look for"
                />
                {query ? (
                  <button type="button" className={s.clear} onClick={clear} aria-label="Clear">
                    <Cross />
                  </button>
                ) : null}
              </span>
              {/* ONE button, with the magnifier inside it. There used to be two (a word and a
                  round icon) that did exactly the same thing. */}
              <button type="submit" className={s.go} disabled={state.status === "searching"}>
                <Glass />
                {state.status === "searching" ? "Searching…" : "Search"}
              </button>
            </form>
          </section>

          {state.status === "failed" ? <p className={s.error}>{state.reason}</p> : null}

          {state.status === "searching" ? (
            <ul className={s.list} aria-busy="true">
              {[0, 1, 2, 3].map(i => (
                <li key={i} className={`${s.row} ${s.skeleton}`} />
              ))}
            </ul>
          ) : null}

          {state.status === "done" && state.domains.length === 0 ? (
            <p className={s.note}>Nothing came back for that. Try a shorter or different name.</p>
          ) : null}

          {state.status === "done" && state.domains.length > 0 ? (
            <>
              <h2 className={s.h2}>Search results</h2>
              <ul className={s.list}>
                {best.map(d => (
                  <Result
                    key={d.name}
                    domain={d}
                    paid={paid}
                    offerOn={offerOn}
                    chosen={chosen?.name === d.name}
                    onSelect={setChosen}
                  />
                ))}
              </ul>

              {more.length ? (
                <>
                  <h2 className={s.h2}>Other extensions</h2>
                  <ul className={`${s.list} ${s.compact}`}>
                    {more.map(d => (
                      <Result
                        key={d.name}
                        domain={d}
                        paid={paid}
                        offerOn={offerOn}
                        chosen={chosen?.name === d.name}
                        onSelect={setChosen}
                      />
                    ))}
                  </ul>
                </>
              ) : null}
            </>
          ) : null}

          {paid && chosen ? (
            <section className={s.panel} aria-label="Get this domain">
              <h2 className={s.h2}>Get {chosen.name}</h2>
              <DomainPipeline
                key={chosen.name}
                compact={!data?.isAdmin}
                preset={{ query: state.asked, found: state.domains, offer: state.offer, domain: chosen.name }}
              />
            </section>
          ) : null}
        </>
      ) : null}
    </div>
  )
}

export default DomainStudio
