import * as React from "react"
import * as s from "./DomainPipeline.module.css"

/**
 * The step list, rendered — FCS-080, FCS-081.
 * ============================================================================
 * Pulled out of DomainPipeline when the second pipeline arrived, because two
 * copies of this would drift and the whole point of matching the Mockup
 * Maker's panel is that every pipeline in the product looks like every other
 * one. Buying a domain and connecting one you own are different jobs; they
 * are not allowed to be different-looking screens.
 *
 * Presentation only. It knows nothing about domains, money or Cloudflare — it
 * takes steps, a record per step, and a render function for whatever a
 * particular step needs to show inside its own body.
 */

const Mark = ({ status }) => {
  if (status === "done") return <span className={s.glyph}>✓</span>
  /* Not a tick. This step is waiting on the customer to go and do something
     somewhere else, and a green tick beside "Change it at your registrar"
     tells them they already have — which is how a domain never gets
     connected and nobody can see why. */
  if (status === "waiting") return <span className={s.glyph}>⋯</span>
  if (status === "failed") return <span className={s.glyph}>✕</span>
  if (status === "running") return <span className={`${s.glyph} ${s.spin}`}>●</span>
  return <span className={s.glyph}>›</span>
}

const PipelineSteps = ({ steps, phases, records, cursor, extra }) => (
  <div className={s.steps}>
    {phases.map(phase => {
      const inPhase = steps.filter(step => step.phase === phase)
      if (!inPhase.length) return null

      return (
        <div className={s.phase} key={phase}>
          <p className={s.phaseName}>{phase}</p>

          {inPhase.map(step => {
            const index = steps.indexOf(step)
            const rec = records[step.id]
            const status = rec?.status || "pending"

            return (
              <div
                className={s.step}
                data-step={step.id}
                data-status={status}
                data-next={index === cursor && !rec ? "true" : undefined}
                key={step.id}
              >
                <span className={s.mark}>
                  <Mark status={status} />
                </span>

                <div className={s.body}>
                  <p className={s.stepTitle}>
                    <strong>
                      {index + 1}. {step.label}
                    </strong>
                    {step.mutates ? <span className={s.writes}>writes</span> : null}
                  </p>
                  <p className={s.detail}>{step.detail}</p>

                  {extra ? extra(step, status) : null}

                  {rec?.log?.length ? <pre className={s.log}>{rec.log.join("\n")}</pre> : null}
                  {rec?.error ? <p className={s.error}>{rec.error}</p> : null}
                </div>
              </div>
            )
          })}
        </div>
      )
    })}
  </div>
)

export default PipelineSteps
