import * as React from "react"
import { NAMESERVER_GUIDES, guideFor } from "../../data/nameserver-guides"
import {
  PHASES,
  STEPS,
  emptyState,
  resume,
  runStep,
} from "../../lib/connect-pipeline"
import PipelineSteps from "./PipelineSteps"
import * as s from "./DomainPipeline.module.css"

/**
 * Connecting a domain they already own — FCS-081.
 * ============================================================================
 * The same panel as the buy pipeline, and deliberately so: a customer should
 * not have to work out that these are two different screens.
 *
 * ── IT CAN BE LEFT AND COME BACK TO ────────────────────────────────────────
 * The middle of this process is a visit to somebody else's website, and that
 * visit may be tomorrow. So the panel reads the stored row on mount and puts
 * itself back where it was: a half-connected domain shows its nameservers and
 * a Check button, not step one with an empty box. Anything less and the
 * customer who comes back the next morning believes they have to start again.
 *
 * ── "NOT YET" IS NOT "FAILED" ──────────────────────────────────────────────
 * A nameserver change takes minutes to a day. The confirm step says so in
 * those words, and offers the button again, rather than showing a red cross
 * that reads as "this is broken".
 */

const nsStep = STEPS.findIndex(step => step.id === "handover")
const confirmStep = STEPS.findIndex(step => step.id === "confirm")
const pointStep = STEPS.findIndex(step => step.id === "point")

const ConnectDomain = () => {
  const [state, setState] = React.useState(emptyState)
  const [records, setRecords] = React.useState({})
  const [cursor, setCursor] = React.useState(0)
  const [running, setRunning] = React.useState(false)
  const [typed, setTyped] = React.useState("")
  const [loading, setLoading] = React.useState(true)

  /* What the server already knows. A domain half-connected yesterday comes
     back as a domain half-connected, not as a blank form. */
  React.useEffect(() => {
    let alive = true
    resume().then(row => {
      if (!alive) return
      setLoading(false)
      if (!row) return

      setTyped(row.domain)
      setState(prev => ({
        ...prev,
        domain: row.domain,
        nameservers: row.nameservers || [],
        status: row.status,
        confirmedAt: row.confirmedAt,
      }))

      const done = { status: "done", log: [] }
      if (row.status === "active") {
        setRecords({
          domain: { ...done, log: [row.domain] },
          preflight: done,
          zone: { ...done, log: [`${row.domain} added.`] },
          handover: done,
          confirm: { ...done, log: [`${row.domain} is confirmed.`] },
          ...(row.wired ? { point: { ...done, log: [`Your website is on ${row.domain}.`] } } : {}),
        })
        setCursor(row.wired ? STEPS.length : pointStep)
      } else {
        setRecords({
          domain: { ...done, log: [row.domain] },
          preflight: done,
          zone: { ...done, log: [`${row.domain} added. Nameservers issued.`] },
          handover: { status: "waiting", log: [] },
        })
        setCursor(nsStep)
      }
    })
    return () => {
      alive = false
    }
  }, [])

  const runFrom = async (from, working) => {
    setRunning(true)
    let carry = working || state

    for (let index = from; index < STEPS.length; index += 1) {
      const step = STEPS[index]
      setCursor(index)
      setRecords(prev => ({ ...prev, [step.id]: { status: "running", log: [] } }))

      const result = await runStep(step, carry)
      carry = { ...carry, ...result.data }
      setState(carry)
      setRecords(prev => ({
        ...prev,
        [step.id]: {
          status: result.success ? "done" : "failed",
          log: result.log || [],
          error: result.error || "",
        },
      }))

      if (!result.success) {
        setCursor(index)
        break
      }

      /* The handover is the customer's job, done on somebody else's website.
         It is marked waiting rather than done: we have no idea whether they
         have been yet, and claiming they have is the one lie this screen
         must not tell. */
      if (step.id === "handover") {
        setRecords(prev => ({ ...prev, handover: { ...prev.handover, status: "waiting" } }))
        setCursor(confirmStep)
        break
      }
      if (index === STEPS.length - 1) setCursor(STEPS.length)
    }

    setRunning(false)
  }

  const start = async event => {
    event?.preventDefault()
    if (!typed.trim() || running) return
    const next = { ...emptyState(), domain: typed.trim(), registrar: state.registrar }
    setState(next)
    setRecords({})
    await runFrom(0, next)
  }

  const guide = guideFor(state.registrar)
  const connected = state.status === "active"
  const waiting = state.nameservers.length > 0 && !connected
  const atConfirm = cursor === confirmStep && !running && waiting
  // Confirmed earlier but never pointed (the page was closed first): offer it, rather than leaving a green tick and nothing.
  const atPoint = connected && cursor === pointStep && !running && !records.point

  if (loading) return <p className={s.note}>Checking for a connected domain…</p>

  const extra = (step, status) => {
    if (step.id === "domain") {
      return (
        <form className={s.form} onSubmit={start}>
          <input
            className={s.input}
            value={typed}
            onChange={event => setTyped(event.target.value)}
            placeholder="yourbusiness.com"
            autoComplete="off"
            spellCheck="false"
            aria-label="The domain you own"
            disabled={running}
          />
          <button type="submit" className={s.go} disabled={running}>
            {running ? "Working…" : state.nameservers.length ? "Start again" : "Connect"}
          </button>
        </form>
      )
    }

    /* The nameservers, and how to hand them over. Shown as soon as they
       exist, and still shown after confirmation — somebody checking their
       registrar months later should find the same two values here. */
    if (step.id === "handover" && state.nameservers.length > 0) {
      return (
        <div className={s.handover}>
          <ol className={s.nsList}>
            {state.nameservers.map(ns => (
              <li key={ns} className={s.ns}>
                <code className={s.nsValue}>{ns}</code>
                <button
                  type="button"
                  className={s.copy}
                  onClick={() => navigator.clipboard?.writeText(ns)}
                >
                  Copy
                </button>
              </li>
            ))}
          </ol>

          <label className={s.pickLabel} htmlFor="ns-registrar">
            Where did you buy the domain?
          </label>
          <select
            id="ns-registrar"
            className={s.select}
            value={state.registrar}
            onChange={event => setState(prev => ({ ...prev, registrar: event.target.value }))}
          >
            {NAMESERVER_GUIDES.map(entry => (
              <option key={entry.id} value={entry.id}>
                {entry.name}
              </option>
            ))}
          </select>

          <ol className={s.guide}>
            {guide.steps.map(line => (
              <li key={line}>{line}</li>
            ))}
          </ol>
          {guide.note ? <p className={s.taken}>{guide.note}</p> : null}
          <p className={s.taken}>
            Menu names change as registrars redesign. Look for “Nameservers”, “DNS”, or “Name
            Servers” — it is always the same two minutes of work.
          </p>
        </div>
      )
    }

    /* The domain already sends visitors somewhere. Say where, and wait to be told to replace it. */
    if (step.id === "point" && status === "failed") {
      return state.existing.length > 0 ? (
        <div className={s.handover} data-testid="replace-records">
          <p className={s.taken}>
            These records at {state.domain} send visitors somewhere else. To put your website there instead we replace them.
            Your email and every other kind of record are left exactly as they are.
          </p>
          <ul className={s.guide}>
            {state.existing.map(r => (
              <li key={`${r.type}-${r.name}-${r.content}`}>
                <code>{r.type}</code> {r.name} → <code>{r.content}</code>
              </li>
            ))}
          </ul>
          <button type="button" className={s.primary} onClick={() => runFrom(pointStep, { ...state, replace: true })} disabled={running}>
            Replace them and use my website
          </button>
        </div>
      ) : (
        <button type="button" className={s.primary} onClick={() => runFrom(pointStep, state)} disabled={running}>
          Try again
        </button>
      )
    }

    if (step.id === "confirm" && status === "failed" && waiting) {
      return (
        <button
          type="button"
          className={s.primary}
          onClick={() => runFrom(confirmStep, state)}
          disabled={running}
        >
          Check again
        </button>
      )
    }

    return null
  }

  return (
    <div className={s.wrap}>
      <header className={s.head}>
        <div>
          <h3 className={s.title}>Already have a domain?</h3>
          <p className={s.note}>
            Point it at your website in {STEPS.length} steps. You change two settings at the
            place you bought it; we do the rest.
          </p>
        </div>
      </header>

      {/* The answer to "is it done", before the steps rather than after. */}
      {connected ? (
        <p className={s.connected}>
          <strong>{state.domain} is connected.</strong> Confirmed
          {state.confirmedAt ? ` on ${new Date(state.confirmedAt).toLocaleDateString()}` : ""}.
        </p>
      ) : waiting ? (
        <p className={s.rehearsal}>
          <strong>Waiting on your registrar.</strong> {state.domain} is set up at our end. Change
          the two nameservers below where you bought it, then press Check again — it can take up
          to 24 hours to go through.
        </p>
      ) : null}

      <PipelineSteps
        steps={STEPS}
        phases={PHASES}
        records={records}
        cursor={cursor}
        extra={extra}
      />

      {atPoint ? (
        <div className={s.gate}>
          <p className={s.gateText}>{state.domain} is connected. Put your website on it?</p>
          <div className={s.gateButtons}>
            <button type="button" className={s.primary} onClick={() => runFrom(pointStep, state)} disabled={running}>
              Put my website on {state.domain}
            </button>
          </div>
        </div>
      ) : null}

      {atConfirm ? (
        <div className={s.gate}>
          <p className={s.gateText}>
            Changed the nameservers at your registrar? Check whether it has gone through.
          </p>
          <div className={s.gateButtons}>
            <button
              type="button"
              className={s.primary}
              onClick={() => runFrom(confirmStep, state)}
              disabled={running}
            >
              {running ? "Checking…" : "Check now"}
            </button>
          </div>
        </div>
      ) : null}
    </div>
  )
}

export default ConnectDomain
