import { buy } from "../../lib/domain-buy"
import * as React from "react"
import { domainsConfigured, unavailableReason } from "../../lib/domains"
import {
  PHASES,
  retailOf,
  STEPS,
  emptyState,
  live,
  money,
  runStep,
  simulate,
} from "../../lib/domain-pipeline"
import PipelineSteps from "./PipelineSteps"
import * as s from "./DomainPipeline.module.css"

/**
 * The domain pipeline, on screen — FCS-080.
 * ============================================================================
 * Deliberately the Mockup Maker's deploy panel: phase headings, a numbered
 * step per row, a mark that goes from chevron to spinner to tick, a "writes"
 * badge on anything that changes the world, and the step's own log underneath
 * it. That panel is already the house style for "a long job, visible while it
 * runs", and somebody who has used one should not have to learn the other.
 *
 * ── IT STOPS BEFORE IT SPENDS ──────────────────────────────────────────────
 * Everything up to and including the price is read-only and runs in one go.
 * The first step that costs money does not start until somebody presses the
 * button that says what it will cost. Registering a domain is not refundable
 * and the amount is not always the one on the first screen, so the figure is
 * re-read and shown again at the point of no return.
 *
 * ── A REHEARSAL IS LABELLED EVERYWHERE ─────────────────────────────────────
 * With no registrar configured the whole flow still walks, because a pipeline
 * you cannot see is a pipeline you cannot review. But every such run carries
 * the word Rehearsal in the header, in the final line, and in each step's log,
 * and the last step says in as many words that nothing was bought. The failure
 * mode worth engineering against here is somebody believing a green tick.
 */

const MUTATING_FIRST = STEPS.findIndex(step => step.mutates)

/**
 * `preset` — FCS-094. The new domain page has its own search and hands over a
 * name the person has already chosen: { query, found, offer, domain }. The
 * panel then starts at the price rather than asking them to search a second
 * time, and hides its own search box so there is one way to look, not two.
 *
 * `compact` — FCS-096. Customers get a price and one button; the ten-step
 * list is an operator's view and stays with the administrators who run the
 * place.
 */
const DomainPipeline = ({ preset = null, compact = false, resume = null }) => {
  const [mode, setMode] = React.useState(domainsConfigured ? "live" : "simulate")
  const [state, setState] = React.useState(emptyState)
  const [records, setRecords] = React.useState({})
  const [cursor, setCursor] = React.useState(0)
  const [running, setRunning] = React.useState(false)
  const [query, setQuery] = React.useState("")

  const transport = mode === "live" ? live : simulate
  const rehearsal = mode !== "live"

  /* Bumped to start again from the name the page handed over. Starting over
     on a panel that has no search box of its own must not leave it blank —
     there would be nothing left to press. */
  const [seedTick, setSeedTick] = React.useState(0)

  const reset = React.useCallback(() => {
    if (preset) {
      setSeedTick(tick => tick + 1)
      return
    }
    setState(emptyState())
    setRecords({})
    setCursor(0)
    setQuery("")
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [Boolean(preset)])

  /**
   * Runs steps from `from` onwards until something stops it.
   *
   * Three things stop it: a failure, a step that needs a decision the state
   * does not yet hold (a name must be chosen before it can be priced), and
   * the first step that writes. The rest runs without ceremony, because
   * clicking Continue through five read-only lookups teaches nobody anything.
   */
  const runFrom = React.useCallback(
    async (from, { through, base } = {}) => {
      setRunning(true)
      let working = { ...(base || state) }

      for (let index = from; index < STEPS.length; index += 1) {
        const step = STEPS[index]

        // A name has to be chosen before anything can be done with it.
        if (step.id !== "search" && !working.domain) {
          setCursor(index)
          break
        }

        setCursor(index)
        setRecords(prev => ({ ...prev, [step.id]: { status: "running", log: [] } }))

        const result = await runStep(transport, step, working)
        working = { ...working, ...result.data }
        setState(working)
        setRecords(prev => ({
          ...prev,
          [step.id]: {
            status: result.success ? "done" : "failed",
            log: result.log || [],
            error: result.error || "",
          },
        }))

        if (!result.success) {
          setCursor(index)
          break
        }

        if (index === STEPS.length - 1) {
          setCursor(STEPS.length)
          break
        }

        // Stop at the edge of spending, every time, even on a re-run.
        if (STEPS[index + 1].mutates && through !== "all") {
          setCursor(index + 1)
          break
        }
      }

      setRunning(false)
    },
    [state, transport]
  )

  /** The search step owns its own input, so it submits rather than continues. */
  const submitSearch = async event => {
    event?.preventDefault()
    if (!query.trim() || running) return
    const next = { ...emptyState(), query }
    setState(next)
    setRecords({})
    setCursor(0)
    setRunning(true)
    setRecords({ search: { status: "running", log: [] } })
    const result = await runStep(transport, STEPS[0], next)
    const merged = { ...next, ...result.data }
    setState(merged)
    setRecords({
      search: {
        status: result.success ? "done" : "failed",
        log: result.log || [],
        error: result.error || "",
      },
    })
    setCursor(result.success ? 1 : 0)
    setRunning(false)
  }

  /** Choosing a name priced it and worked out the coverage in one go. */
  const choose = async (name, base = state) => {
    if (running) return
    const next = { ...base, domain: name }
    setState(next)
    setRunning(true)
    let working = next
    for (const id of ["price", "cover"]) {
      const step = STEPS.find(st => st.id === id)
      setRecords(prev => ({ ...prev, [id]: { status: "running", log: [] } }))
      const result = await runStep(transport, step, working)
      working = { ...working, ...result.data }
      setState(working)
      setRecords(prev => ({
        ...prev,
        [id]: {
          status: result.success ? "done" : "failed",
          log: result.log || [],
          error: result.error || "",
        },
      }))
      if (!result.success) {
        setCursor(STEPS.indexOf(step))
        setRunning(false)
        return
      }
    }
    setCursor(MUTATING_FIRST)
    setRunning(false)
  }

  /* Start from a name the page already chose — on arrival, and again each time
     the person starts over or switches between Live and Rehearsal. This runs
     after the render that changed the mode, so it prices through the NEW
     transport rather than the one the button was pressed under. */
  const seeded = React.useRef(-1)
  React.useEffect(() => {
    if (!preset || seeded.current === seedTick) return
    seeded.current = seedTick
    setCursor(0)
    const base = { ...emptyState(), query: preset.query, found: preset.found, offer: preset.offer }
    setState(base)
    setQuery(preset.query)
    setRecords({
      search: {
        status: "done",
        log: [`${preset.found.length} ${preset.found.length === 1 ? "name" : "names"} came back, priced by the registrar.`],
      },
    })
    choose(preset.domain, base)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [seedTick])

  /* Coming back from Stripe, or from a closed tab (FCS-120). The order already exists on the server and is being carried
     out there; this only picks the screen up at the step where it is waiting, and asks how it is getting on. */
  const resumed = React.useRef(false)
  React.useEffect(() => {
    if (!resume?.orderId || resumed.current) return
    resumed.current = true
    ;(async () => {
      setRunning(true)
      const res = await buy({ action: "status", orderId: resume.orderId })
      const order = res.ok ? res.body.order : null
      if (!order) {
        setRecords({ checkout: { status: "failed", log: [], error: "We could not find that order." } })
        setCursor(STEPS.findIndex(st => st.id === "checkout"))
        setRunning(false)
        return
      }
      const coverage = {
        kind: order.chargedCents > 0 ? "credit" : "covered",
        priceCents: order.retailCents,
        creditCents: Math.max(order.retailCents - order.chargedCents, 0),
        dueCents: order.chargedCents,
        summary: "",
      }
      const base = { ...emptyState(), domain: order.domain, orderId: order.id, coverage, priceCents: order.retailCents }
      setState(base)
      const done = { status: "done", log: [] }
      setRecords({ search: done, price: done, cover: done, checkout: { status: "done", log: [order.chargedCents > 0 ? "Paid." : "Nothing owed."] } })
      setRunning(false)
      await runFrom(STEPS.findIndex(st => st.id === "order"), { through: "all", base })
    })()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [resume?.orderId])

  const available = state.found.filter(d => d.registrable)
  const taken = state.found.filter(d => !d.registrable)
  const coverage = state.coverage
  const atSpend = cursor === MUTATING_FIRST && !running && Boolean(coverage)
  const finished = cursor >= STEPS.length
  const failedStep = STEPS.find(step => records[step.id]?.status === "failed")

  /* What each step shows inside its own body. The panel itself is shared
     with the connect pipeline (FCS-081), so anything specific to buying a
     domain lives here rather than in the renderer. */
  const extra = (step, status) => {
    if (step.id === "search" && preset) return null

    if (step.id === "search") {
      return (
        <>
          <form className={s.form} onSubmit={submitSearch}>
            <input
              className={s.input}
              value={query}
              onChange={event => setQuery(event.target.value)}
              placeholder="ridgelineroofing"
              autoComplete="off"
              spellCheck="false"
              aria-label="Name to look for"
            />
            <button type="submit" className={s.go} disabled={running}>
              {status === "running" ? "Looking…" : "Search"}
            </button>
          </form>

          {available.length > 0 ? (
            <>
              <ul className={s.picks}>
                {available.map(domain => (
                  <li key={domain.name}>
                    <button
                      type="button"
                      className={s.pick}
                      data-domain={domain.name}
                      data-on={state.domain === domain.name ? "true" : undefined}
                      onClick={() => choose(domain.name)}
                      disabled={running}
                    >
                      <span className={s.pickName}>{domain.name}</span>
                      <span className={s.pickPrice}>
                        {retailOf(domain) ? money(retailOf(domain).registrationCents) : "Price not quoted"}
                      </span>
                    </button>
                  </li>
                ))}
              </ul>
              {taken.length > 0 ? (
                <p className={s.taken}>
                  Taken:{" "}
                  {taken.map(d => `${d.name} (${unavailableReason(d).toLowerCase()})`).join(", ")}
                </p>
              ) : null}
            </>
          ) : null}
        </>
      )
    }

    /* What they actually pay, spelled out where the working happened rather
       than only in a total. */
    if (step.id === "cover" && coverage && status === "done") {
      return (
        <div className={s.bill} data-kind={coverage.kind}>
          <span className={s.billRow}>
            <span>{state.domain}, first year</span>
            <span>{money(coverage.priceCents)}</span>
          </span>
          {coverage.creditCents > 0 ? (
            <span className={s.billRow}>
              <span>
                {coverage.kind === "covered" ? "Included with your plan" : "First-year credit"}
              </span>
              <span className={s.credit}>−{money(coverage.creditCents)}</span>
            </span>
          ) : null}
          <span className={`${s.billRow} ${s.billTotal}`}>
            <span>You pay today</span>
            <span>{money(coverage.dueCents)}</span>
          </span>
          {state.renewalCents ? (
            <span className={s.renewal}>
              Renews at {money(state.renewalCents)} a year, which is yours to pay.
            </span>
          ) : null}
        </div>
      )
    }

    return null
  }

  /* ── THE CUSTOMER'S VIEW — FCS-096 ───────────────────────────────────────
     A price, what comes off it, and one button. The same steps run underneath
     when it is pressed; they are simply not displayed, because "Take the
     difference, if any" and "Write the DNS zone" are not things somebody
     buying a domain needs to read. */
  if (compact) {
    const friendly = message =>
      /not built yet|not switched on|could not be reached/i.test(message || "")
        ? "We can't complete this purchase online just yet. Nothing has been charged."
        : message || "That did not go through. Nothing has been charged."
    const working = running ? STEPS[Math.min(cursor, STEPS.length - 1)] : null

    return (
      <div className={s.deal} data-testid="deal">
        {!coverage && !failedStep ? <p className={s.note}>Working out your price…</p> : null}

        {coverage ? (
          <>
            <div className={s.dealPrice}>
              {coverage.creditCents > 0 ? (
                <span className={s.dealWas}>{money(coverage.priceCents)}</span>
              ) : null}
              <span className={s.dealNow} data-free={coverage.dueCents === 0 ? "true" : undefined}>
                {money(coverage.dueCents)}
              </span>
              <span className={s.dealWhen}>first year</span>
            </div>
            <p className={s.dealNote}>
              {coverage.kind === "covered"
                ? "Included with your plan."
                : coverage.kind === "credit"
                  ? `Your ${money(coverage.creditCents)} credit is applied.`
                  : "No credit applies."}
              {state.renewalCents ? ` Renews at ${money(state.renewalCents)} a year.` : ""}
            </p>
          </>
        ) : null}

        {failedStep && !running ? (
          <p className={s.error}>{friendly(records[failedStep.id]?.error)}</p>
        ) : null}

        {finished && !running ? (
          state.live === false && !rehearsal ? (
            <p className={s.dealDone}>
              <strong>Test registration finished.</strong> No real domain was bought and nothing was charged.
            </p>
          ) : (
            <p className={s.dealDone}>
              <strong>{state.domain} is yours</strong> and points at your website. It can take a
              few minutes to start answering everywhere.
            </p>
          )
        ) : (
          <button
            type="button"
            className={s.primary}
            disabled={!coverage || running}
            onClick={() => runFrom(failedStep ? STEPS.indexOf(failedStep) : MUTATING_FIRST, { through: "all" })}
          >
            {running
              ? `Working… ${working ? working.label : ""}`
              : failedStep
                ? "Try again"
                : `Get ${state.domain}`}
          </button>
        )}
      </div>
    )
  }

  return (
    <div className={s.wrap}>
      <header className={s.head}>
        <div>
          <h3 className={s.title}>Get a domain of your own</h3>
          <p className={s.note}>
            {STEPS.length} steps, start to finish: we find the name, buy it, and point it at
            your website. You do not touch a DNS record.
          </p>
        </div>
        <div className={s.modes}>
          {/* Live is not offered when there is nothing to be live against:
              a switch that cannot work is a support ticket. */}
          {domainsConfigured ? (
            <button
              type="button"
              className={s.mode}
              data-on={mode === "live" ? "true" : undefined}
              onClick={() => {
                setMode("live")
                reset()
              }}
              disabled={running}
            >
              Live
            </button>
          ) : null}
          <button
            type="button"
            className={s.mode}
            data-on={rehearsal ? "true" : undefined}
            onClick={() => {
              setMode("simulate")
              reset()
            }}
            disabled={running}
          >
            Rehearsal
          </button>
        </div>
      </header>

      {rehearsal ? (
        <p className={s.rehearsal}>
          <strong>Rehearsal.</strong> Names and prices below are real, straight from the
          registrar — but nothing is bought, no money moves, and no domain becomes live.
        </p>
      ) : null}

      <PipelineSteps
        steps={STEPS}
        phases={PHASES}
        records={records}
        cursor={cursor}
        extra={extra}
      />

      {/* The point of no return, as its own bar. Nothing above this has cost
          anything; the button says the amount so nobody presses it to find
          out what it does. */}
      {atSpend ? (
        <div className={s.gate}>
          <p className={s.gateText}>
            {coverage.dueCents > 0 ? (
              <>
                Next comes payment of <strong>{money(coverage.dueCents)}</strong> and the
                registration of <strong>{state.domain}</strong>. A registered domain cannot be
                handed back.
              </>
            ) : (
              <>
                Next we register <strong>{state.domain}</strong> for you — nothing to pay. A
                registered domain cannot be handed back.
              </>
            )}
          </p>
          <div className={s.gateButtons}>
            <button
              type="button"
              className={s.primary}
              onClick={() => runFrom(MUTATING_FIRST, { through: "all" })}
            >
              {coverage.dueCents > 0
                ? `Pay ${money(coverage.dueCents)} and register`
                : `Register ${state.domain}`}
            </button>
            <button type="button" className={s.ghost} onClick={reset}>
              Start over
            </button>
          </div>
        </div>
      ) : null}

      {failedStep && !running ? (
        <div className={s.gate}>
          <p className={s.gateText}>
            Stopped at step {STEPS.indexOf(failedStep) + 1}, {failedStep.label}. Nothing after it
            ran.
          </p>
          <div className={s.gateButtons}>
            <button
              type="button"
              className={s.primary}
              onClick={() => runFrom(STEPS.indexOf(failedStep), { through: "all" })}
            >
              Try that step again
            </button>
            <button type="button" className={s.ghost} onClick={reset}>
              Start over
            </button>
          </div>
        </div>
      ) : null}

      {finished && !running ? (
        <div className={s.done} data-rehearsal={rehearsal ? "true" : undefined}>
          {rehearsal ? (
            <p className={s.gateText}>
              <strong>Rehearsal finished.</strong> {state.domain} was not bought and is not live.
              Every step above was answered with made-up data.
            </p>
          ) : (
            <p className={s.gateText}>
              <strong>{state.domain} is yours</strong> and points at your website. It can take a
              few minutes to start answering everywhere.
            </p>
          )}
          <button type="button" className={s.ghost} onClick={reset}>
            Do another
          </button>
        </div>
      ) : null}
    </div>
  )
}

export default DomainPipeline
